INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenbanken > BASE-Prinzipien
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Stellt Basically Available sicher, dass ein System auch bei Teilausfällen verfügbar bleibt?', 2, '[{"text": "Ja", "correct": true, "because": "Basically Available priorisiert Verfügbarkeit"}, {"text": "Nein", "correct": false, "because": "Definition von Basically Available"}]'),
('00000000-0000-0000-0000-000000000000', 'Bedeutet Soft State, dass der Zustand eines Systems auch ohne neue Eingaben ändern kann?', 2, '[{"text": "Ja", "correct": true, "because": "Soft State erlaubt temporäre Inkonsistenzen"}, {"text": "Nein", "correct": false, "because": "Kernprinzip von Soft State"}]'),
('00000000-0000-0000-0000-000000000000', 'Garantieren die BASE-Prinzipien sofortige Konsistenz nach jeder Operation?', 2, '[{"text": "Nein", "correct": true, "because": "Eventual Consistency verzögert Konsistenz"}, {"text": "Ja", "correct": false, "because": "Gegensatz zu ACID"}]'),
('00000000-0000-0000-0000-000000000000', 'Heißt Eventual Consistency, dass alle Daten irgendwann konsistent werden?', 2, '[{"text": "Ja", "correct": true, "because": "Eventual Consistency strebt langfristige Konsistenz an"}, {"text": "Nein", "correct": false, "because": "Definition von Eventual Consistency"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind die BASE-Prinzipien typisch für relationale Datenbanken wie MySQL?', 2, '[{"text": "Nein", "correct": true, "because": "BASE ist typisch für NoSQL-Systeme"}, {"text": "Ja", "correct": false, "because": "Relationale DBs folgen meist ACID"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welches BASE-Prinzip priorisiert die Verfügbarkeit eines Systems selbst bei Teilausfällen?', 2, '[{"text": "Basically Available", "correct": true, "because": "Fokus auf Verfügbarkeit"}, {"text": "Soft State", "correct": false, "because": "Flexibler Zustand"}, {"text": "Eventual Consistency", "correct": false, "because": "Langfristige Konsistenz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip beschreibt, dass der Zustand eines Systems sich ohne Eingaben ändern kann?', 3, '[{"text": "Soft State", "correct": true, "because": "Zustand kann sich selbst anpassen"}, {"text": "Basically Available", "correct": false, "because": "Verfügbarkeit"}, {"text": "Eventual Consistency", "correct": false, "because": "Konsistenz über Zeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches BASE-Prinzip garantiert, dass Daten irgendwann konsistent werden?', 2, '[{"text": "Eventual Consistency", "correct": true, "because": "Konsistenz wird erreicht"}, {"text": "Soft State", "correct": false, "because": "Flexibler Zustand"}, {"text": "Basically Available", "correct": false, "because": "Verfügbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip erlaubt temporäre Inkonsistenzen zugunsten von Verfügbarkeit?', 2, '[{"text": "Soft State", "correct": true, "because": "Erlaubt temporäre Abweichungen"}, {"text": "Eventual Consistency", "correct": false, "because": "Fokus auf Konsistenz"}, {"text": "Basically Available", "correct": false, "because": "Fokus auf Verfügbarkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches BASE-Prinzip steht im Gegensatz zur sofortigen Konsistenz von ACID?', 2, '[{"text": "Eventual Consistency", "correct": true, "because": "Verzögerte Konsistenz"}, {"text": "Soft State", "correct": false, "because": "Flexibler Zustand"}, {"text": "Basically Available", "correct": false, "because": "Verfügbarkeit"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien gehören zu den BASE-Prinzipien?', 4, '[{"text": "Basically Available", "correct": true, "because": "Verfügbarkeit"}, {"text": "Soft State", "correct": true, "because": "Flexibler Zustand"}, {"text": "Eventual Consistency", "correct": true, "because": "Langfristige Konsistenz"}, {"text": "Atomicity", "correct": false, "because": "ACID-Prinzip"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Eigenschaften beschreiben Basically Available?', 3, '[{"text": "Hohe Verfügbarkeit", "correct": true, "because": "Priorität bei Ausfällen"}, {"text": "Toleranz bei Teilausfällen", "correct": true, "because": "System bleibt nutzbar"}, {"text": "Keine Downtime", "correct": true, "because": "Ziel ist Verfügbarkeit"}, {"text": "Sofortige Konsistenz", "correct": false, "because": "Nicht garantiert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Merkmale hat Soft State in BASE?', 4, '[{"text": "Temporäre Inkonsistenz", "correct": true, "because": "Erlaubt Abweichungen"}, {"text": "Selbstanpassung", "correct": true, "because": "Zustand kann sich ändern"}, {"text": "Keine festen Regeln", "correct": true, "because": "Flexibilität"}, {"text": "Dauerhafte Speicherung", "correct": false, "because": "Durability in ACID"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte gehören zu Eventual Consistency?', 3, '[{"text": "Langfristige Konsistenz", "correct": true, "because": "Irgendwann konsistent"}, {"text": "Verzögerte Synchronisation", "correct": true, "because": "Konsistenz nicht sofort"}, {"text": "Eventuelle Übereinstimmung", "correct": true, "because": "Alle Knoten werden gleich"}, {"text": "Sofortige Updates", "correct": false, "because": "Gegensatz zu BASE"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Unterschiede gibt es zwischen BASE und ACID?', 3, '[{"text": "Verfügbarkeit über Konsistenz", "correct": true, "because": "BASE priorisiert Verfügbarkeit"}, {"text": "Eventuelle statt sofortige Konsistenz", "correct": true, "because": "BASE vs. ACID"}, {"text": "Flexibler Zustand", "correct": true, "because": "Soft State vs. Consistency"}, {"text": "Alles-oder-Nichts", "correct": false, "because": "ACID, nicht BASE"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Basically Available priorisiert Verfügbarkeit vor Konsistenz. b) Es garantiert sofortige Konsistenz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verfügbarkeit ja, Konsistenz nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Soft State erlaubt temporäre Inkonsistenzen. b) Es erfordert ständige Benutzereingaben.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Inkonsistenz ja, Eingaben nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eventual Consistency strebt langfristige Konsistenz an. b) Es ist typisch für relationale Datenbanken.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Konsistenz ja, NoSQL typisch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Basically Available toleriert Teilausfälle. b) Soft State erfordert sofortige Konsistenz.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Ausfälle ja, Konsistenz nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Eventual Consistency verzögert Konsistenz zugunsten von Verfügbarkeit. b) BASE-Prinzipien sind für ACID-Systeme typisch.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verzögerung ja, ACID nein"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

